-- ELEMENT-TYPE: function
-- ELEMENT-ID: FUNCTION:authn:login_attempt(text, text, text)

CREATE OR REPLACE FUNCTION authn.login_attempt(
    p_team_name text, p_password text, p_source text,
    OUT token_id uuid, OUT wait_ms integer, OUT expires_at timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $authn_function$
DECLARE
    normalized_name text;
    tenant_id uuid;
    tenant_enabled boolean;
    subject_id uuid;
    password_hash text;
    hash_for_check text;
    credential_generation bigint;
    token_ttl bigint;
    window_seconds bigint;
    throttle_threshold bigint;
    throttle_step_ms bigint;
    throttle_max_ms bigint;
    password_matches boolean;
    failure boolean;
    issued_at timestamptz;
    source_key text;
    event_time timestamptz;
    window_begin timestamptz;
    failure_count bigint;
    response_interval_ms bigint;
    old_allowed_at timestamptz;
    next_allowed_at timestamptz;
    counter_id uuid;
BEGIN
    normalized_name := public.authn_normalize_team_name(p_team_name);
    SELECT tenant.id, tenant.enabled, subject.id,
           credential.password_hash, credential.generation
      INTO tenant_id, tenant_enabled, subject_id,
           password_hash, credential_generation
    FROM public.tenants AS tenant
    LEFT JOIN public.tenant_auth_subjects AS subject
      ON subject.tenant_id = tenant.id
    LEFT JOIN public.tenant_credentials AS credential
      ON credential.auth_subject_id = subject.id
    WHERE tenant.name_normalized = normalized_name
      AND tenant.retired_at IS NULL;
    token_ttl := authn.setting_positive_integer('auth.token_ttl_seconds');
    window_seconds := authn.setting_positive_integer('auth.team_login.window_seconds');
    throttle_threshold := authn.setting_positive_integer('auth.team_login.throttle_threshold');
    throttle_step_ms := authn.setting_positive_integer('auth.team_login.throttle_step_ms');
    throttle_max_ms := authn.setting_positive_integer('auth.team_login.throttle_max_ms');
    -- max_failures と lock_seconds のキーは既存投入物に残し、このログイン経路では読まない。
    -- 無い名前・無効なテナント・誤ったパスワードも cost 12 を一度照合する。
    hash_for_check := CASE
        WHEN password_hash ~ '^\$2[aby]\$12\$[./A-Za-z0-9]{53}$'
        THEN password_hash
        ELSE '$2a$12$abcdefghijklmnopqrstuug/hOvRed88u/sCt2izp9NATk2M3qMx6'
    END;
    password_matches := coalesce(
        authn_crypto.crypt(coalesce(p_password, ''), hash_for_check)
        = password_hash, false);
    failure := tenant_id IS NULL OR tenant_enabled IS NOT TRUE
        OR subject_id IS NULL OR credential_generation IS NULL
        OR NOT password_matches OR token_ttl IS NULL
        OR window_seconds IS NULL OR throttle_threshold IS NULL
        OR throttle_step_ms IS NULL OR throttle_max_ms IS NULL;
    IF NOT failure THEN
        issued_at := pg_catalog.clock_timestamp();
        token_id := pg_catalog.gen_random_uuid();
        expires_at := issued_at + token_ttl * INTERVAL '1 second';
        INSERT INTO public.tenant_tokens
            (id, tenant_id, auth_subject_id, credential_generation,
             expires_at, last_used_at)
        VALUES (token_id, tenant_id, subject_id, credential_generation,
                expires_at, issued_at);
        wait_ms := 0;
        RETURN;
    END IF;

    token_id := NULL;
    wait_ms := 0;
    expires_at := NULL;
    IF window_seconds IS NULL OR throttle_threshold IS NULL
       OR throttle_step_ms IS NULL OR throttle_max_ms IS NULL THEN
        RETURN;
    END IF;

    -- 試行元はアプリが正規化して渡す。名前とウィンドウはロック鍵に含めない。
    source_key := 'src:' || coalesce(nullif(pg_catalog.lower(
        pg_catalog.btrim(p_source)), ''), 'unknown');
    PERFORM pg_catalog.pg_advisory_xact_lock(
        87001224, pg_catalog.hashtext(source_key)
    );
    event_time := pg_catalog.clock_timestamp();
    window_begin := pg_catalog.to_timestamp(
        pg_catalog.floor(extract(epoch FROM event_time)
                         / window_seconds::numeric) * window_seconds
    );
    SELECT coalesce(pg_catalog.sum(counter.attempt_count), 0),
           pg_catalog.max(counter.locked_until)
      INTO failure_count, old_allowed_at
    FROM public.rate_limit_counters AS counter
    WHERE counter.scope_key = source_key
      AND counter.window_start >= window_begin - window_seconds * INTERVAL '1 second'
      AND counter.window_start <= window_begin;
    IF failure_count <= throttle_threshold THEN
        response_interval_ms := 0;
    ELSIF failure_count <= throttle_threshold * 2 THEN
        response_interval_ms := throttle_step_ms;
    ELSIF failure_count <= throttle_threshold * 4 THEN
        response_interval_ms := throttle_step_ms * 2;
    ELSE
        response_interval_ms := throttle_step_ms * 4;
    END IF;
    wait_ms := LEAST(
        throttle_max_ms,
        GREATEST(
            0, pg_catalog.ceil(extract(epoch FROM
                (old_allowed_at - event_time)) * 1000)
        )
    )::integer;
    next_allowed_at := GREATEST(
        event_time, coalesce(old_allowed_at, event_time)
    ) + response_interval_ms * INTERVAL '1 millisecond';
    -- record_failure の locked_until は拒否用のロック期限であり、予約票とは意味が異なる。
    SELECT counter.id INTO counter_id
    FROM public.rate_limit_counters AS counter
    WHERE counter.scope_key = source_key
      AND counter.window_start = window_begin
    ORDER BY counter.id LIMIT 1 FOR UPDATE;
    IF counter_id IS NULL THEN
        INSERT INTO public.rate_limit_counters
            (id, scope_key, window_start, attempt_count, locked_until)
        VALUES (pg_catalog.gen_random_uuid(), source_key, window_begin,
                1, next_allowed_at);
    ELSE
        UPDATE public.rate_limit_counters
           SET attempt_count = attempt_count + 1,
               locked_until = next_allowed_at
         WHERE id = counter_id;
    END IF;
    RETURN;
END;
$authn_function$;
ALTER FUNCTION authn.login_attempt(text, text, text) OWNER TO pitchlog_auth_fn_owner;
REVOKE ALL PRIVILEGES ON FUNCTION authn.login_attempt(text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authn.login_attempt(text, text, text) TO pitchlog_app;

-- ELEMENT-TYPE: function
-- ELEMENT-ID: FUNCTION:authn:verify_token(uuid)

CREATE OR REPLACE FUNCTION authn.verify_token(
    p_token_id uuid, OUT tenant_id uuid, OUT expires_at timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $authn_function$
DECLARE
    initial_subject_id uuid;
    current_generation bigint;
    token_tenant_id uuid;
    token_subject_id uuid;
    token_generation bigint;
    token_expires_at timestamptz;
    tenant_enabled boolean;
    tenant_retired_at timestamptz;
    subject_tenant_id uuid;
    token_ttl bigint;
    checked_at timestamptz;
BEGIN
    SELECT token.auth_subject_id INTO initial_subject_id
      FROM public.tenant_tokens AS token WHERE token.id = p_token_id;
    IF initial_subject_id IS NULL THEN RETURN; END IF;
    SELECT credential.generation INTO current_generation
      FROM public.tenant_credentials AS credential
     WHERE credential.auth_subject_id = initial_subject_id FOR SHARE;
    IF current_generation IS NULL THEN RETURN; END IF;
    SELECT token.tenant_id, token.auth_subject_id,
           token.credential_generation, token.expires_at,
           tenant.enabled, tenant.retired_at, subject.tenant_id
      INTO token_tenant_id, token_subject_id, token_generation,
           token_expires_at, tenant_enabled, tenant_retired_at,
           subject_tenant_id
      FROM public.tenant_tokens AS token
      LEFT JOIN public.tenants AS tenant ON tenant.id = token.tenant_id
      LEFT JOIN public.tenant_auth_subjects AS subject
        ON subject.id = token.auth_subject_id
     WHERE token.id = p_token_id FOR UPDATE OF token;
    checked_at := pg_catalog.clock_timestamp();
    token_ttl := authn.setting_positive_integer('auth.token_ttl_seconds');
    IF token_tenant_id IS NULL OR token_subject_id <> initial_subject_id
       OR subject_tenant_id IS DISTINCT FROM token_tenant_id
       OR token_generation <> current_generation
       OR tenant_enabled IS NOT TRUE OR tenant_retired_at IS NOT NULL
       OR token_expires_at <= checked_at OR token_ttl IS NULL THEN
        RETURN;
    END IF;
    tenant_id := token_tenant_id;
    expires_at := checked_at + token_ttl * INTERVAL '1 second';
    UPDATE public.tenant_tokens
       SET last_used_at = checked_at,
           expires_at = verify_token.expires_at
     WHERE id = p_token_id;
    RETURN;
END;
$authn_function$;
ALTER FUNCTION authn.verify_token(uuid) OWNER TO pitchlog_auth_fn_owner;
REVOKE ALL PRIVILEGES ON FUNCTION authn.verify_token(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authn.verify_token(uuid) TO pitchlog_app;
GRANT EXECUTE ON FUNCTION authn.verify_token(uuid) TO pitchlog_initial_auth_verifier;

-- ELEMENT-TYPE: function
-- ELEMENT-ID: FUNCTION:authn:logout(uuid)

CREATE OR REPLACE FUNCTION authn.logout(p_token_id uuid)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $authn_function$
DECLARE
    previous_last_used_at timestamptz;
    logged_out_at timestamptz;
BEGIN
    SELECT token.last_used_at INTO previous_last_used_at
      FROM public.tenant_tokens AS token WHERE token.id = p_token_id FOR UPDATE;
    IF NOT FOUND THEN RETURN; END IF;
    logged_out_at := pg_catalog.clock_timestamp();
    UPDATE public.tenant_tokens
       SET expires_at = greatest(logged_out_at, previous_last_used_at)
     WHERE id = p_token_id;
END;
$authn_function$;
ALTER FUNCTION authn.logout(uuid) OWNER TO pitchlog_auth_fn_owner;
REVOKE ALL PRIVILEGES ON FUNCTION authn.logout(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authn.logout(uuid) TO pitchlog_app;

-- ELEMENT-TYPE: function
-- ELEMENT-ID: FUNCTION:authn:observe_rate_limit_counters()

CREATE OR REPLACE FUNCTION authn.observe_rate_limit_counters(
    OUT out_of_window_rows bigint, OUT distinct_scope_keys bigint
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $authn_function$
DECLARE
    window_seconds bigint;
    window_begin timestamptz;
BEGIN
    window_seconds := authn.setting_positive_integer('auth.team_login.window_seconds');
    IF window_seconds IS NULL THEN
        RAISE EXCEPTION 'ログインの監視設定が不正です' USING ERRCODE = '22023';
    END IF;
    window_begin := pg_catalog.to_timestamp(
        pg_catalog.floor(extract(epoch FROM pg_catalog.clock_timestamp())
                         / window_seconds::numeric) * window_seconds
    );

    -- 累積量は src:・team:・admin: を含む表全体で数える。鍵の前置きでは絞らない。
    -- 索引の先頭列でまとめ、索引にある scope_key と window_start だけを読む。
    SELECT coalesce(pg_catalog.sum(scopes.outside_count), 0),
           pg_catalog.count(*)
      INTO out_of_window_rows, distinct_scope_keys
    FROM (
        SELECT counter.scope_key,
               pg_catalog.count(*) FILTER (
                   WHERE counter.window_start <> window_begin
               ) AS outside_count
        FROM public.rate_limit_counters AS counter
        GROUP BY counter.scope_key
    ) AS scopes;
END;
$authn_function$;
ALTER FUNCTION authn.observe_rate_limit_counters() OWNER TO pitchlog_auth_fn_owner;
REVOKE ALL PRIVILEGES ON FUNCTION authn.observe_rate_limit_counters() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authn.observe_rate_limit_counters() TO pitchlog_management_fn_owner;

-- ELEMENT-TYPE: function
-- ELEMENT-ID: FUNCTION:authn:change_password(uuid, text, text)

CREATE OR REPLACE FUNCTION authn.change_password(p_token_id uuid, p_current_password text, p_new_password text)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $authn_function$
DECLARE
    initial_subject_id uuid;
    current_generation bigint;
    current_hash text;
    token_tenant_id uuid;
    token_subject_id uuid;
    token_generation bigint;
    token_expires_at timestamptz;
    tenant_enabled boolean;
    tenant_retired_at timestamptz;
    subject_tenant_id uuid;
    checked_at timestamptz;
BEGIN
    SELECT token.auth_subject_id INTO initial_subject_id
      FROM public.tenant_tokens AS token WHERE token.id = p_token_id;
    IF initial_subject_id IS NULL THEN RETURN false; END IF;
    SELECT credential.generation, credential.password_hash
      INTO current_generation, current_hash
      FROM public.tenant_credentials AS credential
     WHERE credential.auth_subject_id = initial_subject_id FOR UPDATE;
    IF current_generation IS NULL THEN RETURN false; END IF;
    SELECT token.tenant_id, token.auth_subject_id,
           token.credential_generation, token.expires_at,
           tenant.enabled, tenant.retired_at, subject.tenant_id
      INTO token_tenant_id, token_subject_id, token_generation,
           token_expires_at, tenant_enabled, tenant_retired_at,
           subject_tenant_id
      FROM public.tenant_tokens AS token
      LEFT JOIN public.tenants AS tenant ON tenant.id = token.tenant_id
      LEFT JOIN public.tenant_auth_subjects AS subject
        ON subject.id = token.auth_subject_id
     WHERE token.id = p_token_id FOR SHARE OF token;
    checked_at := pg_catalog.clock_timestamp();
    IF token_tenant_id IS NULL OR token_subject_id <> initial_subject_id
       OR subject_tenant_id IS DISTINCT FROM token_tenant_id
       OR token_generation <> current_generation
       OR tenant_enabled IS NOT TRUE OR tenant_retired_at IS NOT NULL
       OR token_expires_at <= checked_at
       OR authn.setting_positive_integer('auth.token_ttl_seconds') IS NULL THEN
        RETURN false;
    END IF;
    IF authn.password_policy_ok(p_new_password) IS NOT TRUE THEN
        RETURN false;
    END IF;
    IF authn_crypto.crypt(coalesce(p_current_password, ''),
                         current_hash) IS DISTINCT FROM current_hash THEN
        RETURN false;
    END IF;
    UPDATE public.tenant_credentials
       SET password_hash = authn_crypto.crypt(p_new_password,
                                               authn_crypto.gen_salt('bf', 12)),
           generation = generation + 1, password_changed_at = checked_at
     WHERE auth_subject_id = initial_subject_id;
    RETURN true;
END;
$authn_function$;
ALTER FUNCTION authn.change_password(uuid, text, text) OWNER TO pitchlog_auth_fn_owner;
REVOKE ALL PRIVILEGES ON FUNCTION authn.change_password(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authn.change_password(uuid, text, text) TO pitchlog_app;

